const content=document.querySelector('#app-content'),modal=document.querySelector('#modal'),modalContent=document.querySelector('#modal-content');
const AUTH=document.querySelector('#auth-layer');
const labels={dashboard:'Visão geral',library:'Biblioteca',studio:'Estúdio de materiais',study:'Estudo ativo',flashcards:'Flashcards',planning:'Planejamento',reviews:'Revisões',performance:'Meu desempenho',settings:'Configurações'};
let generatedLoaded=false;
const state={user:null,spaces:[],space:null,prefs:null,notebooks:[],subjects:[],materials:[],dashboard:null,aiAvailable:false,view:'dashboard',generated:[],questions:[],cards:[],session:null,sessionIndex:0,sessionResults:[],activeCard:0,cardRevealed:false,search:'',timerStarted:0};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=async(url,options={})=>{const headers=new Headers(options.headers||{});if(!(options.body instanceof FormData)&&options.body!==undefined)headers.set('Content-Type','application/json');if(state.space?.id)headers.set('X-Space-Id',String(state.space.id));const response=await fetch(url,{...options,headers,credentials:'same-origin'});const type=response.headers.get('content-type')||'';const data=type.includes('application/json')?await response.json():await response.blob();if(!response.ok){const error=new Error(data?.error||`Erro ${response.status}`);error.status=response.status;error.code=data?.code;throw error}return data};
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800)}
function showError(error){if(error.status===401){state.user=null;renderAuth('login');return}toast(error.message||'Não foi possível concluir a ação.')}
function openModal(html){modalContent.innerHTML=`<div class="modal-content">${html}</div>`;modal.showModal()}
function closeModal(){modal.close()}
function heading(kicker,title,copy,action=''){return `<div class="page-heading"><div><span class="eyebrow">${esc(kicker)}</span><h1>${esc(title)}</h1><p>${esc(copy)}</p></div>${action}</div>`}
function button(action,label,kind=''){return `<button class="button ${kind}" data-action="${action}">${label}</button>`}
function subjectOptions(selected=''){return state.subjects.map(s=>`<option value="${s.id}" ${Number(selected)===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}
function notebookOptions(selected=''){return `<option value="">Sem caderno</option>${state.notebooks.map(n=>`<option value="${n.id}" ${Number(selected)===n.id?'selected':''}>${esc(n.name)}</option>`).join('')}`}
function sourceChoices(selectedIds=[]){if(!state.materials.length)return `<div class="empty-state"><strong>Adicione suas fontes primeiro</strong><p>Envie PDFs, apresentações ou documentos para montar seu espaço de conhecimento.</p><button class="button small" data-view-link="library">Abrir biblioteca →</button></div>`;return `<div class="source-choices">${state.materials.map(m=>`<label class="source-choice"><input type="checkbox" name="materialIds" value="${m.id}" ${selectedIds.includes(m.id)?'checked':''} ${m.process_status!=='ready'?'disabled':''}><span class="file-icon ${m.mime_type==='application/pdf'?'pdf':''}">${fileType(m)}</span><span><strong>${esc(m.name)}</strong><small>${esc(m.subject_name||'Sem assunto')} · ${statusText(m.process_status)}</small></span></label>`).join('')}</div>`}
function selectedFrom(form){return [...form.querySelectorAll('input[name="materialIds"]:checked')].map(x=>Number(x.value))}
function fileType(m){return (m.original_name.split('.').pop()||'ARQ').toUpperCase().slice(0,4)}
function statusText(s){return ({queued:'Na fila',processing:'Processando…',ready:'Pronto para uso',failed:'Falha no processamento',reference:'Referência externa'})[s]||s}
function dateFmt(value,opts={day:'numeric',month:'short'}){if(!value)return '—';const date=new Date(`${String(value).slice(0,10)}T12:00:00`);return date.toLocaleDateString('pt-BR',opts)}
function longDate(){return new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}
function currentDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function minutesText(total=0){const m=Math.max(0,Number(total)||0);return `${Math.floor(m/60)}h ${String(m%60).padStart(2,'0')}`}
function renderMarkdown(text){const lines=esc(text).split('\n');let html='',list=false;for(const line of lines){const l=line.trim();if(/^[-*]\s+/.test(l)){if(!list){html+='<ul>';list=true}html+=`<li>${l.replace(/^[-*]\s+/,'').replace(/\[S(\d+)\]/g,'<span class="citation">S$1</span>')}</li>`;continue}if(list){html+='</ul>';list=false}if(!l){html+='<br>';continue}const content=l.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\[S(\d+)\]/g,'<span class="citation">S$1</span>');if(/^###\s/.test(l))html+=`<h3>${content.slice(4)}</h3>`;else if(/^##\s/.test(l))html+=`<h2>${content.slice(3)}</h2>`;else if(/^#\s/.test(l))html+=`<h2>${content.slice(2)}</h2>`;else html+=`<p>${content}</p>`}if(list)html+='</ul>';return html}
async function boot(){try{const me=await api('/api/auth/me');state.user=me.user;state.spaces=me.spaces||[];const wanted=Number(localStorage.getItem('study-space-id'));state.space=state.spaces.find(s=>s.id===wanted)||state.spaces[0]||null;if(!state.space){await loadSpace();return}await loadSpace();document.querySelector('#auth-layer').hidden=true;document.querySelector('.app-shell').classList.remove('auth-hidden');render()}catch{renderAuth(location.pathname==='/reset-password'?'reset':'login')}}
async function loadSpace(){if(!state.space)return;const data=await api('/api/bootstrap');Object.assign(state,{space:data.space,spaces:data.spaces||state.spaces,prefs:data.prefs,notebooks:data.notebooks||[],subjects:data.subjects||[],materials:data.materials||[],dashboard:data.dashboard,aiAvailable:data.aiAvailable});localStorage.setItem('study-space-id',String(state.space.id));syncShell()}
function syncShell(){document.querySelector('#profile-name').textContent=state.user?.name||'Meu perfil';document.querySelector('#profile-avatar').textContent=(state.user?.name||'?').slice(0,1).toUpperCase();document.querySelector('#material-count').textContent=state.materials.length;document.querySelector('#week-hours').textContent=minutesText(state.dashboard?.weeklyMinutes||0);document.querySelector('#week-goal').textContent=`/ ${minutesText(state.dashboard?.weeklyGoal||300)}`;const pct=Math.min(100,100*(state.dashboard?.weeklyMinutes||0)/Math.max(1,state.dashboard?.weeklyGoal||300));document.querySelector('#week-progress-bar').style.width=`${pct}%`;document.querySelector('#week-message').textContent=pct>=100?'Meta semanal concluída.':pct>0?'Você está avançando no seu ritmo.':'Seu progresso semanal aparece aqui.';document.querySelector('#review-nav-dot').style.display=state.dashboard?.reviewDue?'block':'none';document.querySelector('#today-label').textContent=longDate();const select=document.querySelector('#space-select');select.innerHTML=state.spaces.map(s=>`<option value="${s.id}" ${s.id===state.space?.id?'selected':''}>${esc(s.name)}</option>`).join('');document.querySelector('.workspace-label').textContent=(state.space?.name||'SEU ESPAÇO').toUpperCase()}
function setView(view){state.view=view;state.search='';state.session=null;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('#breadcrumb-current').textContent=labels[view]||view;document.querySelector('#sidebar').classList.remove('open');render()}
function render(){syncShell();switch(state.view){case'dashboard':renderDashboard();break;case'library':renderLibrary();break;case'studio':renderStudio();break;case'study':renderStudy();break;case'flashcards':renderFlashcards();break;case'planning':renderPlanning();break;case'reviews':renderReviews();break;case'performance':renderPerformance();break;case'settings':renderSettings();break;default:renderDashboard()}}

function renderAuth(mode='login',message=''){document.querySelector('.app-shell').classList.add('auth-hidden');AUTH.hidden=false;const resetToken=new URLSearchParams(location.search).get('token')||'';const isLogin=mode==='login',isSignup=mode==='signup',isRecovery=mode==='recovery',isReset=mode==='reset';AUTH.innerHTML=`<div class="auth-layout"><div class="auth-aside"><a class="brand" href="#"><span class="brand-mark"><svg viewBox="0 0 32 32"><path d="M5 8.5c4.2-2 8-1.8 11 1.2v16c-3-3-6.8-3.2-11-1.2v-16Zm22 0c-4.2-2-8-1.8-11 1.2v16c3-3 6.8-3.2 11-1.2v-16Z"/></svg></span><span>study<span class="brand-light">space</span></span></a><div class="auth-aside-copy"><span class="eyebrow">SEU ESPAÇO DE APRENDIZAGEM</span><h1>Aprender é<br>voltar ao que<br><em>importa.</em></h1><p>Organize as fontes. Pratique lembrar. Construa conhecimento ao longo do tempo.</p><div class="auth-points"><span>01 <b>Organize seus materiais</b></span><span>02 <b>Estude de forma ativa</b></span><span>03 <b>Revise no momento certo</b></span></div></div><span class="auth-aside-foot">STUDY SPACE · PLATAFORMA DE APRENDIZAGEM</span></div><div class="auth-main"><div class="auth-box"><span class="eyebrow">${isLogin?'BEM-VINDA DE VOLTA':isSignup?'COMECE POR AQUI':isRecovery?'RECUPERAR ACESSO':'NOVA SENHA'}</span><h2>${isLogin?'Entre no seu espaço':isSignup?'Crie sua conta':isRecovery?'Recupere sua conta':'Defina uma nova senha'}</h2><p>${isLogin?'Retome seu plano, seus materiais e suas revisões.':isSignup?'Seu ambiente de aprendizagem, organizado do seu jeito.':isRecovery?'Enviaremos um link de redefinição para seu e-mail.':'Escolha uma senha com pelo menos 10 caracteres.'}</p>${message?`<div class="form-alert">${esc(message)}</div>`:''}<form id="${isLogin?'login-form':isSignup?'signup-form':isRecovery?'recovery-form':'reset-form'}">${isSignup?`<label class="form-label" for="auth-name">Seu nome</label><input id="auth-name" name="name" class="form-control" autocomplete="name" required minlength="2">`:''}${!isReset?`<label class="form-label" for="auth-email">E-mail</label><input id="auth-email" name="email" class="form-control" type="email" autocomplete="email" required>`:''}${isLogin||isSignup||isReset?`<label class="form-label" for="auth-password">${isReset?'Nova senha':'Senha'}</label><input id="auth-password" name="password" class="form-control" type="password" minlength="10" autocomplete="${isLogin?'current-password':'new-password'}" required>`:''}${isReset?`<input type="hidden" name="token" value="${esc(resetToken)}">`:''}<button class="button auth-submit" type="submit">${isLogin?'Entrar':isSignup?'Criar minha conta':isRecovery?'Enviar link de redefinição':'Salvar nova senha'} <span>→</span></button></form><div class="auth-switch">${isLogin?`<button data-auth="recovery">Esqueci minha senha</button><span>·</span><button data-auth="signup">Criar uma conta</button>`:isSignup?`Já tem conta? <button data-auth="login">Entrar</button>`:isRecovery?`Lembrou a senha? <button data-auth="login">Voltar ao login</button>`:`<button data-auth="login">Voltar ao login</button>`}</div><small class="auth-privacy">Seus espaços, materiais e progresso ficam separados por conta. Configure SMTP no servidor para habilitar recuperação de senha.</small></div></div></div>`}

function renderDashboard(){const d=state.dashboard||{},empty=!state.materials.length&&!state.subjects.length;const items=d.plan||[];content.innerHTML=`<section class="welcome-row"><div><span class="eyebrow">${esc(longDate())}</span><h1>Olá, ${esc(state.user?.name?.split(' ')[0]||'estudante')} <span class="greeting-spark">✳</span></h1><p>Um passo de cada vez. <strong>O que você vai aprender hoje?</strong></p></div><button class="button" data-action="add-material">＋ Adicionar material</button></section>${empty?`<section class="onboarding"><div class="onboarding-copy"><span class="eyebrow">SEU ESPAÇO COMEÇA AQUI</span><h2>Traga sua primeira aula<br>para o Study Space.</h2><p>Adicione um material, organize por assunto e use suas fontes para estudar. O conteúdo fica privado no seu espaço.</p><div class="onboarding-steps"><span><i>1</i> Crie seus assuntos</span><span><i>2</i> Adicione materiais</span><span><i>3</i> Gere seu primeiro plano</span></div><div class="onboarding-actions"><button class="button" data-action="add-subject">＋ Criar assunto</button><button class="button secondary" data-action="add-material">Adicionar material</button></div></div><div class="onboarding-art"><div class="onboard-leaf">✳</div><div class="onboard-book"></div><span class="onboard-note">ANOTAÇÕES<br>QUE CRIAM RAÍZES</span></div></section>`:`<div class="dashboard-grid"><div class="main-column"><section class="hero-card"><div class="hero-copy"><span class="eyebrow">SUA ROTINA DE HOJE</span><h2>${d.reviewDue?`${d.reviewDue} revisão${d.reviewDue===1?'':'ões'} aguardam<br>sua atenção.`:'Um espaço para estudar<br>com intenção.'}</h2><p>${items.length?`${items.length} atividade${items.length===1?'':'s'} · ${d.planTotal||0} minutos previstos`:'Gere uma rotina com seus assuntos e disponibilidade.'}</p><button class="button light" data-view-link="planning">Abrir planejamento <span>→</span></button></div><div class="hero-art" aria-hidden="true"><div class="book-shape"></div><span class="hero-flower">✳</span></div></section><section class="metrics"><article class="metric"><div class="metric-top"><span>Tempo nesta semana</span><span class="metric-icon">◷</span></div><strong>${minutesText(d.weeklyMinutes)}</strong><small>meta ${minutesText(d.weeklyGoal)}</small></article><article class="metric"><div class="metric-top"><span>Questões respondidas</span><span class="metric-icon">✳</span></div><strong>${d.questions||0}</strong><small>últimos 30 dias</small></article><article class="metric"><div class="metric-top"><span>Taxa de acertos</span><span class="metric-icon">◉</span></div><strong>${Math.round((d.accuracy||0)*100)}%</strong><small>${d.mastered||0} assuntos dominados</small></article></section><section class="panel"><div class="panel-heading"><h3>Seu plano de hoje</h3><button class="text-link" data-view-link="planning">Ver semana →</button></div>${scheduleMarkup(items)}</section><section class="panel"><div class="panel-heading"><h3>Materiais recentes</h3><button class="text-link" data-view-link="library">Abrir biblioteca →</button></div>${materialsList(state.materials.slice(0,4))}</section></div><div class="right-column"><section class="panel"><div class="panel-heading"><h3>Revisões próximas</h3><button class="text-link" data-view-link="reviews">Ver todas</button></div>${(d.dueSoon||[]).length?d.dueSoon.slice(0,4).map(r=>`<div class="recent-item"><span class="file-icon">↻</span><span class="recent-meta"><strong>${esc(r.subject_name)}</strong><small>${dateFmt(r.due_at)} · etapa ${r.stage}</small></span><span class="tag review">${r.due_at<=d.today?'Hoje':'Em breve'}</span></div>`).join(''):'<p class="study-note">Você não tem revisões pendentes. Ao concluir um estudo, o ciclo de revisão será criado automaticamente.</p>'}</section><section class="panel focus-panel"><span class="eyebrow">ESTUDO ATIVO</span><p><strong>Pratique para fixar</strong><br>Responda antes de ver a explicação e acompanhe seu domínio por assunto.</p><button class="button small" data-view-link="study">Começar uma sessão →</button></section><section class="panel"><div class="panel-heading"><h3>Últimas sessões</h3><button class="text-link" data-view-link="performance">Desempenho →</button></div>${(d.activity||[]).length?d.activity.map(a=>`<div class="recent-item"><span class="file-icon">◈</span><span class="recent-meta"><strong>${esc(a.subject_name||'Estudo')}</strong><small>${dateFmt(a.completed_at,{day:'numeric',month:'short'})} · ${a.questions_correct}/${a.questions_total} acertos</small></span></div>`).join(''):'<p class="study-note">Suas sessões concluídas vão aparecer aqui.</p>'}</section></div></div>`}`}
function scheduleMarkup(items){if(!items?.length)return `<div class="empty-state compact"><strong>Nenhuma atividade planejada</strong><p>Gere uma agenda semanal com seus assuntos e tempo disponível.</p><button class="button small" data-view-link="planning">Organizar semana</button></div>`;return `<div class="schedule-list">${items.map(i=>`<div class="schedule-item"><div class="time-box">${i.estimated_minutes}<span>MIN</span></div><div class="schedule-info"><strong>${esc(i.title||i.subject_name)}</strong><small>${i.kind==='review'?'Recuperação ativa · revisão espaçada':i.kind==='reinforcement'?'Reforço · desempenho abaixo do esperado':'Conteúdo novo · prática orientada'}</small></div><span class="tag ${i.kind==='review'?'review':i.kind==='reinforcement'?'focus':''}">${i.kind==='review'?'Revisão':i.kind==='reinforcement'?'Reforço':'Conteúdo novo'}</span></div>`).join('')}</div>`}
function materialsList(list){return list.length?`<div class="recent-list">${list.map(m=>`<div class="recent-item"><span class="file-icon ${m.mime_type==='application/pdf'?'pdf':''}">${fileType(m)}</span><span class="recent-meta"><strong>${esc(m.name)}</strong><small>${esc(m.subject_name||'Sem assunto')} · ${statusText(m.process_status)}</small></span><button class="text-link" data-action="material-detail" data-id="${m.id}" aria-label="Detalhes">···</button></div>`).join('')}</div>`:`<div class="empty-state compact"><strong>Sua biblioteca está vazia</strong><p>Adicione uma aula, apostila ou fonte externa.</p><button class="button small" data-action="add-material">Adicionar material</button></div>`}

function renderLibrary(){const list=state.materials.filter(m=>(m.name+' '+(m.subject_name||'')+' '+m.original_name).toLowerCase().includes(state.search.toLowerCase()));content.innerHTML=`${heading('CONHECIMENTO ORGANIZADO','Minha biblioteca','Arquivos, referências e materiais gerados, organizados pelos assuntos que você aprende.',button('add-material','＋ Adicionar material'))}<div class="library-toolbar"><label class="search-field"><input id="library-search" type="search" placeholder="Buscar materiais, assuntos ou nomes de arquivo…" value="${esc(state.search)}" aria-label="Buscar biblioteca"></label><button class="button secondary" data-action="add-subject">＋ Assunto</button><button class="button secondary" data-action="add-notebook">＋ Caderno</button><button class="button secondary" data-action="add-reference">↗ Importar URL</button></div><div class="library-summary"><span><strong>${state.materials.length}</strong> materiais</span><span><strong>${state.subjects.length}</strong> assuntos</span><span><strong>${state.notebooks.length}</strong> cadernos</span></div><div class="material-grid">${list.length?list.map(m=>`<article class="material-card"><div class="material-card-top"><span class="file-icon ${m.mime_type==='application/pdf'?'pdf':''}">${fileType(m)}</span><span class="tag ${m.process_status==='ready'?'ready':m.process_status==='failed'?'failed':''}">${statusText(m.process_status)}</span></div><h3>${esc(m.name)}</h3><p>${esc(m.subject_name||'Sem assunto')} · ${formatBytes(m.file_size)}</p>${m.process_error?`<p class="processing-error">${esc(m.process_error)}</p>`:''}<div class="material-footer"><span>v${m.version} · ${dateFmt(m.created_at,{day:'numeric',month:'short',year:'numeric'})}</span><div class="material-card-actions">${m.has_file?`<a href="/api/materials/${m.id}/file" class="text-link" target="_blank" rel="noreferrer">Abrir ↗</a>`:''}<button data-action="material-detail" data-id="${m.id}">Detalhes</button></div></div></article>`).join(''):`<div class="empty-state"><span class="empty-icon">▤</span><strong>${state.search?'Nenhum material encontrado':'Sua biblioteca começa aqui'}</strong><p>${state.search?'Experimente uma palavra diferente.':'Envie um documento ou adicione uma fonte externa. O processamento ficará visível aqui.'}</p>${state.search?'':`<button class="button small" data-action="add-material">Adicionar material</button>`}</div>`}</div><p class="helper">Arquivos e conteúdo extraído são privados e armazenados no servidor local deste projeto. A geração por IA envia somente os trechos recuperados para a API configurada no servidor.</p>`;const input=document.querySelector('#library-search');input.addEventListener('input',e=>{state.search=e.target.value;renderLibrary();const el=document.querySelector('#library-search');el.focus();el.setSelectionRange(state.search.length,state.search.length)})}
function formatBytes(n){if(!n)return 'URL';if(n<1024)return `${n} B`;if(n<1024*1024)return `${(n/1024).toFixed(0)} KB`;return `${(n/1024/1024).toFixed(1)} MB`}

function renderStudio(){const generated=state.generated;content.innerHTML=`${heading('TRANSFORME SUAS FONTES','Estúdio de materiais','Gere recursos de aprendizagem com referências rastreáveis às suas aulas.',button('new-studio','＋ Nova geração'))}<div class="studio-layout"><section class="panel studio-form-panel"><div class="panel-heading"><h3>O que você quer criar?</h3><span class="ai-indicator ${state.aiAvailable?'available':'unavailable'}">${state.aiAvailable?'IA conectada':'IA não configurada'}</span></div>${!state.aiAvailable?`<div class="config-notice"><strong>Configure a chave da IA</strong><p>Adicione OPENAI_API_KEY ao arquivo .env para habilitar a geração. O sistema usará somente as fontes que você marcar, com referências.</p></div>`:''}<form id="studio-form"><label class="form-label">Fontes selecionadas</label>${sourceChoices()}<div class="form-two"><div><label class="form-label">Tipo de material</label><select class="form-control" name="type"><option value="summary">Resumo</option><option value="guide">Guia de estudo</option><option value="workbook">Apostila teórica</option><option value="comparison">Tabela comparativa</option><option value="concept_map">Mapa conceitual</option><option value="notes">Fichamento</option><option value="flashcards">Flashcards</option><option value="key_concepts">Conceitos fundamentais</option><option value="review_guide">Roteiro de revisão</option><option value="deep_dive">Aprofundamento</option></select></div><div><label class="form-label">Profundidade</label><select class="form-control" name="depth"><option value="concise">Sintético</option><option value="balanced" selected>Equilibrado</option><option value="detailed">Detalhado</option></select></div></div><label class="form-label">Assunto associado</label><select class="form-control" name="subjectId"><option value="">Sem assunto específico</option>${subjectOptions()}</select><label class="form-label">Objetivo do material</label><textarea class="form-control textarea" name="goal" placeholder="Ex.: compreender a regulação da pressão arterial e comparar os mecanismos envolvidos." required></textarea><label class="form-label">Título</label><input class="form-control" name="title" placeholder="Será sugerido pelo tipo de material"><div class="form-actions"><button class="button" ${state.aiAvailable?'':'disabled'}>Gerar com fontes selecionadas →</button></div></form></section><aside class="panel studio-library"><div class="panel-heading"><h3>Materiais gerados</h3><span class="tag">${generated.length}</span></div>${generated.length?generated.map(g=>`<button class="generated-row" data-action="open-generated" data-id="${g.id}"><span class="generated-icon">✳</span><span><strong>${esc(g.title)}</strong><small>${esc(g.kind)} · ${g.version} versão${g.version===1?'':'ões'}</small></span><b>→</b></button>`).join(''):'<p class="study-note">Suas sínteses, guias e materiais integrados aparecem aqui com histórico de versões.</p>'}<div class="studio-note"><strong>Como a rastreabilidade funciona</strong><p>Cada trecho usado na geração recebe um marcador de fonte. Você pode conferir o documento, a página quando disponível e revisar cada versão salva.</p></div></aside></div>`;if(!generatedLoaded)loadGenerated().then(()=>{generatedLoaded=true;if(state.view==='studio')renderStudio()}).catch(showError)}

function renderStudy(){if(state.session){renderActiveSession();return}content.innerHTML=`${heading('RECUPERAÇÃO ATIVA','Estudo ativo','Responda às questões antes de consultar a explicação. Seu desempenho atualiza o domínio do assunto.') }<div class="study-layout"><section class="panel study-setup"><div class="panel-heading"><h3>Configurar uma sessão</h3></div>${!state.aiAvailable?`<div class="config-notice compact-notice"><strong>A geração de questões requer IA.</strong><p>Configure OPENAI_API_KEY no servidor. As questões serão baseadas nas fontes que você selecionar.</p></div>`:''}<form id="session-form"><label class="form-label">Assunto</label><select class="form-control" name="subjectId" required>${subjectOptions()}</select><label class="form-label">Materiais de referência</label>${sourceChoices()}<div class="form-three"><div><label class="form-label">Questões</label><input class="form-control" name="quantity" type="number" min="1" max="30" value="8"></div><div><label class="form-label">Formato</label><select class="form-control" name="type"><option value="multiple_choice">Múltipla escolha</option><option value="true_false">Verdadeiro ou falso</option><option value="short_answer">Resposta curta</option><option value="cloze">Lacunas</option><option value="case">Caso clínico</option></select></div><div><label class="form-label">Dificuldade</label><select class="form-control" name="difficulty"><option value="mixed">Variada</option><option value="easy">Fácil</option><option value="medium">Intermediária</option><option value="hard">Avançada</option></select></div></div><label class="form-label">Objetivo da sessão</label><input class="form-control" name="goal" value="Recuperar os conceitos principais e identificar lacunas de aprendizagem."><div class="form-actions"><button class="button" ${state.aiAvailable?'':'disabled'}>Gerar e começar →</button></div></form></section><aside class="study-side"><section class="panel"><div class="panel-heading"><h3>Banco de questões</h3><button class="text-link" data-action="refresh-questions">Atualizar</button></div><div id="question-bank" class="study-note">Carregando questões salvas…</div></section><section class="panel study-note"><strong>Suas fontes, seu escopo</strong>A geração recupera trechos apenas dos materiais selecionados. A explicação aparece após cada resposta e inclui as fontes usadas.</section></aside></div>`;loadQuestions()}
async function loadQuestions(){try{state.questions=await api('/api/questions');const el=document.querySelector('#question-bank');if(!el)return;el.innerHTML=state.questions.length?state.questions.slice(0,7).map(q=>`<div class="bank-row"><span class="bank-type">${q.question_type==='multiple_choice'?'MCQ':esc(q.question_type)}</span><span><strong>${esc(q.prompt)}</strong><small>${esc(q.subject_name||'Assunto')} · ${q.attempts} tentativas${q.attempts?` · ${Math.round(q.correct/q.attempts*100)}% acerto`:''}</small></span></div>`).join(''):'Questões geradas e tentativas anteriores aparecem aqui.'}catch(e){showError(e)}}
function renderActiveSession(){const session=state.session,questions=session.questions,index=state.sessionIndex,q=questions[index],result=state.sessionResults[index];if(!q){content.innerHTML='<section class="empty-state">Nenhuma questão nesta sessão.</section>';return}const progress=index/questions.length*100;content.innerHTML=`${heading(`${esc(session.subject.name)} · ${session.reviewId?'REVISÃO':'SESSÃO'}`,'Uma pergunta de cada vez.','Tente responder de memória; a explicação e as fontes aparecem depois da resposta.',`<button class="button secondary" data-action="leave-session">Sair da sessão</button>`)}<div class="study-layout"><section class="study-card"><div class="study-topline"><span>QUESTÃO ${index+1} DE ${questions.length}</span><span>${session.correct||0} acertos · ${Math.floor((Date.now()-state.timerStarted)/60000)} min</span></div><div class="study-progress"><span style="width:${progress}%"></span></div><span class="question-label">${esc(q.question_type.replaceAll('_',' ').toUpperCase())} · ${esc(q.difficulty)}</span><h2 class="question-text">${esc(q.prompt)}</h2>${q.options?.length?`<div class="answer-list">${q.options.map((o,i)=>`<button class="answer-option ${result?i===Number(result.submittedAnswer)?(result.correct?'correct':'wrong'):'' :''}" data-action="submit-answer" data-index="${i}" ${result?'disabled':''}><span class="answer-letter">${'ABCDEFG'[i]}</span>${esc(o)}</button>`).join('')}</div>`:`<form id="answer-form"><label class="form-label" for="short-answer">Sua resposta</label><textarea id="short-answer" class="form-control textarea" name="answer" placeholder="Escreva sua resposta…" ${result?'disabled':''} required>${result?esc(result.submittedAnswer):''}</textarea>${result?'':`<div class="form-actions"><button class="button">Enviar resposta →</button></div>`}</form>`}${result?`<div class="answer-feedback"><strong>${result.correct?'Resposta correta.':result.score>=.4?'Resposta parcialmente correta.':'Vamos revisar este ponto.'}</strong> ${esc(result.feedback)}${result.modelAnswer?`<p><strong>Resposta esperada:</strong> ${esc(result.modelAnswer)}</p>`:''}${result.explanation?`<p>${esc(result.explanation)}</p>`:''}${result.sources?.length?`<div class="citation-list">${result.sources.map(s=>`<span class="citation">${esc(s.citation)}</span> ${esc(s.material_name)}${s.page?`, p. ${s.page}`:''}`).join('<br>')}</div>`:''}</div><div class="study-actions"><span class="study-note">Domínio atual: ${Math.round((result.mastery||0)*100)}%</span><button class="button" data-action="next-question">${index===questions.length-1?'Concluir sessão':'Próxima questão'} →</button></div>`:''}</section><aside class="study-side"><section class="panel study-note"><strong>Sobre esta sessão</strong>${esc(session.subject.name)}<br>${questions.length} questões · fontes selecionadas<br>${session.reviewId?'Etapa de revisão agendada':'Prática de recuperação ativa'}</section><section class="panel study-note"><strong>Um lembrete</strong>O desempenho é associado ao assunto e alimenta seu plano. Você pode rever seu histórico em “Meu desempenho”.</section></aside></div>`}

function renderFlashcards(){content.innerHTML=`${heading('REPETIÇÃO ESPAÇADA','Flashcards','Pratique a lembrança e avalie o quanto foi fácil recuperar a resposta.',`<button class="button" data-action="add-flashcard">＋ Criar flashcard</button>`)}<div class="flashcard-toolbar"><select class="select-field" id="flash-subject"><option value="">Todos os assuntos</option>${subjectOptions()}</select><button class="button secondary" data-action="load-cards">Revisar vencidos</button><button class="button secondary" data-action="generate-cards" ${state.aiAvailable?'':'disabled'}>✳ Gerar com IA</button></div><div id="flashcard-stage" class="flashcard-stage"><div class="panel study-note">Carregando flashcards…</div></div><section class="panel flashcard-list-panel"><div class="panel-heading"><h3>Seus cartões</h3><button class="text-link" data-action="load-cards">Atualizar</button></div><div id="flashcard-list"></div></section>`;loadCards()}

function renderPlanning(){const weekStart=mondayOf(currentDate());content.innerHTML=`${heading('ORGANIZE SEU RITMO','Planejamento','Distribua revisões, conteúdo novo e reforço dentro do tempo que você tem.',`<button class="button" data-action="generate-plan">↻ Recalcular semana</button>`)}<div class="planning-toolbar"><label>Semana <input class="form-control date-control" id="week-start" type="date" value="${weekStart}"></label><button class="button secondary" data-action="planning-settings">⚙ Disponibilidade</button></div><div id="planning-body"><section class="panel study-note">Carregando planejamento…</section></div>`;loadPlan(weekStart)}
function mondayOf(value){const d=new Date(`${value}T12:00:00`);d.setDate(d.getDate()-(d.getDay()+6)%7);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
async function loadPlan(week){try{const plan=await api(`/api/plans?weekStart=${encodeURIComponent(week)}`);const el=document.querySelector('#planning-body');if(!el)return;const days=Array.from({length:7},(_,i)=>{const d=new Date(`${week}T12:00:00`);d.setDate(d.getDate()+i);const date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {date,name:d.toLocaleDateString('pt-BR',{weekday:'short'}),label:d.toLocaleDateString('pt-BR',{day:'numeric',month:'short'})}});el.innerHTML=`<div class="week-strip">${days.map(d=>`<div class="week-day ${d.date===currentDate()?'selected':''}">${d.name}<strong>${d.label}</strong></div>`).join('')}</div><div class="planning-grid"><section class="panel"><div class="panel-heading"><h3>${plan.items.length} atividades para a semana</h3><span class="tag">Meta ${minutesText(plan.target_minutes)}</span></div>${plan.items.length?days.map(d=>{const day=plan.items.filter(i=>i.scheduled_for===d.date);return day.length?`<section class="day-group"><h4>${esc(d.name)} · ${esc(d.label)}</h4>${day.map(i=>`<div class="plan-item ${i.status==='done'?'plan-done':''}"><span class="plan-kind ${i.kind}">${i.kind==='review'?'↻':i.kind==='reinforcement'?'!':'＋'}</span><div class="plan-item-main"><strong>${esc(i.title)}</strong><small>${i.kind==='review'?`Revisão ${i.review_stage||''}`:i.kind==='reinforcement'?'Reforço de assunto':'Conteúdo novo'} · ${i.estimated_minutes} min</small></div><div class="plan-item-controls"><input aria-label="Data da atividade" type="date" value="${i.scheduled_for}" data-plan-date="${i.id}"><button class="icon-button" data-action="toggle-plan-item" data-id="${i.id}" data-status="${i.status}">${i.status==='done'?'✓':'○'}</button>${i.kind==='review'&&i.status!=='done'?`<button class="text-link" data-action="start-review" data-id="${i.review_id}">Estudar →</button>`:''}</div></div>`).join('')}</section>`:''}).join(''):`<div class="empty-state"><strong>Nenhuma atividade nesta semana</strong><p>Adicione assuntos e gere um plano para distribuir estudos e revisões.</p><button class="button small" data-action="generate-plan">Gerar planejamento</button></div>`}</section><aside class="right-column"><section class="panel"><div class="panel-heading"><h3>Tempo disponível</h3></div><strong class="plan-total">${minutesText(plan.items.reduce((n,i)=>n+i.estimated_minutes,0))}</strong><p class="study-note">programado nesta semana · meta ${minutesText(plan.target_minutes)}</p><div class="progress-track"><span style="width:${Math.min(100,plan.items.reduce((n,i)=>n+i.estimated_minutes,0)/Math.max(plan.target_minutes,1)*100)}%"></span></div></section><section class="panel study-note"><strong>Como o plano prioriza</strong>Revisões vencidas primeiro, depois assuntos com baixo domínio e conteúdos ainda não estudados. A disponibilidade diária limita o número de atividades.</section></aside></div>`}catch(e){showError(e)}}

function renderReviews(){content.innerHTML=`${heading('CONSOLIDE NO TEMPO','Revisões espaçadas','Os ciclos começam quando você conclui a sessão inicial. Intervalos padrão: 7, 14, 21 e 30 dias.',`<button class="button secondary" data-action="generate-plan">Adicionar à agenda</button>`)}<div class="review-filter"><button class="filter-chip selected" data-review-filter="pending">Pendentes</button><button class="filter-chip" data-review-filter="completed">Concluídas</button><button class="filter-chip" data-review-filter="all">Todas</button></div><section class="panel"><div id="reviews-body" class="reviews-body">Carregando ciclos…</div></section>`;loadReviews('pending')}
async function loadReviews(filter){try{const rows=await api('/api/reviews');const el=document.querySelector('#reviews-body');if(!el)return;const selected=filter==='all'?rows:rows.filter(r=>filter==='completed'?r.status==='completed':r.status!=='completed');el.innerHTML=selected.length?selected.map(r=>`<div class="review-entry"><div class="review-name"><span class="file-icon">↻</span><div><strong>${esc(r.subject_name)}</strong><small>${esc(r.started_at?'Ciclo iniciado '+dateFmt(r.started_at):'Revisão agendada')}</small></div></div><span>${dateFmt(r.due_at,{day:'numeric',month:'short',year:'numeric'})}</span><span class="tag ${r.status==='completed'?'ready':'review'}">${r.status==='completed'?'Concluída':r.due_at<currentDate()?'Atrasada':`Etapa ${r.stage} · ${[7,14,21,30][r.stage-1]} dias`}</span><div class="review-actions">${r.status!=='completed'?`<button class="button small" data-action="start-review" data-id="${r.id}">Revisar agora</button><button class="text-link" data-action="reschedule-review" data-id="${r.id}">Adiar</button>`:`<span class="status done">✓ ${Math.round((r.score||0)*100)}%</span>`}</div></div>`).join(''):`<div class="empty-state"><strong>${filter==='completed'?'Nenhuma revisão concluída ainda':'Nenhuma revisão agendada'}</strong><p>${filter==='completed'?'Quando concluir uma revisão, o histórico ficará registrado aqui.':'Conclua uma sessão de estudo inicial para criar o primeiro ciclo.'}</p>${!state.materials.length?`<button class="button small" data-view-link="library">Adicionar materiais</button>`:''}</div>`;document.querySelectorAll('[data-review-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.reviewFilter===filter))}catch(e){showError(e)}}

function renderPerformance(){content.innerHTML=`${heading('ACOMPANHE SEU PROCESSO','Meu desempenho','Observe a retenção, o domínio por assunto e a consistência ao longo do tempo.') }<div class="performance-body">Carregando desempenho…</div>`;loadPerformance()}
async function loadPerformance(){try{const data=await api('/api/performance');const body=document.querySelector('.performance-body');if(!body)return;const s=data.summary;const daily=data.sessions.slice(-14);const max=Math.max(1,...daily.map(x=>x.minutes));body.innerHTML=`<section class="metrics performance-metrics"><article class="metric"><div class="metric-top"><span>Questões respondidas</span><span class="metric-icon">✳</span></div><strong>${s.questions}</strong><small>histórico total</small></article><article class="metric"><div class="metric-top"><span>Taxa média de acertos</span><span class="metric-icon">◉</span></div><strong>${Math.round(s.accuracy*100)}%</strong><small>com correção registrada</small></article><article class="metric"><div class="metric-top"><span>Revisões concluídas</span><span class="metric-icon">↻</span></div><strong>${data.reviews.completed||0}</strong><small>${data.reviews.overdue||0} atrasadas</small></article></section><div class="performance-grid"><section class="panel"><div class="panel-heading"><h3>Tempo de estudo · últimos 14 dias</h3></div><div class="chart">${daily.length?daily.map(x=>`<div class="chart-col"><span class="chart-value">${x.minutes?x.minutes+'m':''}</span><div class="chart-bar ${x.day===currentDate()?'highlight':''}" style="height:${Math.max(x.minutes?8:2,x.minutes/max*82)}%" title="${x.minutes} minutos"></div><small>${dateFmt(x.day,{day:'numeric',month:'short'})}</small></div>`).join(''):'<span class="study-note">Suas sessões concluídas vão compor o gráfico.</span>'}</div></section><section class="panel"><div class="panel-heading"><h3>Domínio por assunto</h3><button class="text-link" data-action="add-subject">＋ Assunto</button></div>${data.subjects.length?data.subjects.map(s=>`<div class="mastery-row"><div class="mastery-label"><strong>${esc(s.name)}</strong><span>${s.attempts?`${s.correct}/${s.attempts} acertos`:'Sem tentativas'}</span></div><div class="mastery-track"><span style="width:${Math.round(s.mastery*100)}%"></span></div><b>${Math.round(s.mastery*100)}%</b></div>`).join(''):'<p class="study-note">Crie assuntos e pratique com questões para acompanhar seu domínio.</p>'}</section><section class="panel performance-history"><div class="panel-heading"><h3>Histórico recente de respostas</h3><button class="text-link" data-action="show-attempts">Ver detalhes</button></div><div id="attempt-history"><p class="study-note">Carregando…</p></div></section></div>`;loadAttempts()}catch(e){showError(e)}}
async function loadAttempts(){try{const rows=await api('/api/attempts');const el=document.querySelector('#attempt-history');if(!el)return;el.innerHTML=rows.length?rows.slice(0,6).map(a=>`<div class="history-row"><span class="history-result ${a.is_correct?'correct':'incorrect'}">${a.is_correct?'✓':'×'}</span><span><strong>${esc(a.subject_name||'Assunto')}</strong><small>${esc(a.prompt||'Questão removida')}</small></span><small>${dateFmt(a.attempted_at,{day:'numeric',month:'short'})}</small></div>`).join(''):'<p class="study-note">As tentativas aparecem aqui depois da primeira sessão.</p>'}catch(e){showError(e)}}

function renderSettings(){content.innerHTML=`${heading('PREFERÊNCIAS DO ESTUDANTE','Configurações','Gerencie seu perfil, os espaços de estudo e os dados da conta.')}<div class="settings-grid"><div class="main-column"><section class="panel"><div class="panel-heading"><h3>Perfil</h3></div><form id="profile-form"><label class="form-label">Nome</label><input class="form-control" name="name" value="${esc(state.user?.name)}" required><label class="form-label">E-mail</label><input class="form-control" name="email" type="email" value="${esc(state.user?.email)}" required><div class="form-actions"><button class="button">Salvar perfil</button></div></form></section><section class="panel"><div class="panel-heading"><h3>Disponibilidade de estudos</h3></div><form id="preferences-form"><label class="form-label">Minutos disponíveis por dia</label><input class="form-control" name="dailyMinutes" type="number" min="15" max="600" value="${state.prefs?.daily_minutes||90}"><label class="form-label">Meta semanal em minutos</label><input class="form-control" name="weeklyMinutes" type="number" min="30" max="3000" value="${state.prefs?.weekly_minutes||450}"><label class="form-label">Dias disponíveis</label><div class="weekday-checks">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((d,i)=>`<label><input type="checkbox" name="availableDays" value="${i}" ${(JSON.parse(state.prefs?.available_days||'[1,2,3,4,5]')).includes(i)?'checked':''}> ${d}</label>`).join('')}</div><label class="form-label">Horário preferido</label><input class="form-control" name="preferredStart" type="time" value="${state.prefs?.preferred_start||'18:00'}"><div class="form-actions"><button class="button">Salvar disponibilidade</button></div></form></section><section class="panel"><div class="panel-heading"><h3>Alterar senha</h3></div><form id="password-form"><label class="form-label">Senha atual</label><input class="form-control" name="currentPassword" type="password" required><label class="form-label">Nova senha</label><input class="form-control" name="newPassword" type="password" minlength="10" required><div class="form-actions"><button class="button secondary">Atualizar senha</button></div></form></section><section class="panel"><div class="panel-heading"><h3>Espaços de estudo</h3><button class="text-link" data-action="add-space">＋ Criar espaço</button></div>${state.spaces.map(s=>`<div class="space-row"><span class="file-icon">⌂</span><span><strong>${esc(s.name)}</strong><small>${s.id===state.space?.id?'Espaço atual':'Espaço independente'}</small></span><button class="text-link" data-action="switch-space" data-id="${s.id}">${s.id===state.space?.id?'Ativo':'Abrir'}</button></div>`).join('')}</section></div><aside class="right-column"><section class="panel"><div class="panel-heading"><h3>Privacidade e dados</h3></div><p class="study-note">Seus materiais e progresso pertencem à sua conta. Exporte uma cópia ou solicite exclusão completa da conta.</p><button class="button secondary full-button" data-action="export-data">Baixar meus dados</button><div class="danger-zone"><strong>Excluir conta</strong><p>Remove permanentemente seu perfil, espaços, materiais, arquivos e histórico.</p><button class="button danger" data-action="delete-account">Excluir minha conta</button></div></section><section class="panel study-note"><strong>Conexões</strong><p>IA: <span class="ai-indicator ${state.aiAvailable?'available':'unavailable'}">${state.aiAvailable?'Configurada':'OPENAI_API_KEY ausente'}</span></p><p>Recuperação por e-mail: configure SMTP_HOST, SMTP_USER, SMTP_PASS e MAIL_FROM no .env.</p></section><button class="button secondary full-button" data-action="logout">Sair da conta</button></aside></div>`}

function addMaterialModal(){openModal(`<h2>Adicionar material</h2><p class="modal-intro">Envie uma aula ou referência para seu espaço privado. Formatos suportados: PDF, PPTX, DOCX, texto e imagens.</p><form id="material-form"><label class="form-label">Arquivo</label><input class="form-control file-input" type="file" name="file" accept=".pdf,.ppt,.pptx,.doc,.docx,.png,.jpg,.jpeg,.webp,.tif,.tiff,.txt,.md,.csv" required><p class="helper">Limite de 25 MB. PDF, DOCX, PPTX e texto são extraídos em segundo plano. Imagens exigem OCR, não habilitado nesta versão.</p><label class="form-label">Nome</label><input class="form-control" name="name" placeholder="Opcional; usa o nome do arquivo"><label class="form-label">Assunto</label><select class="form-control" name="subjectId"><option value="">Sem assunto</option>${subjectOptions()}</select><label class="form-label">Caderno</label><select class="form-control" name="notebookId">${notebookOptions()}</select><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button">Enviar e processar</button></div></form>`)}
function addSubjectModal(){openModal(`<h2>Novo assunto</h2><p class="modal-intro">O assunto conecta materiais, avaliações, domínio e revisões.</p><form id="subject-form"><label class="form-label">Nome</label><input class="form-control" name="name" placeholder="Ex.: Fisiologia cardiovascular" required><div class="form-two"><div><label class="form-label">Prioridade · 1 a 5</label><select class="form-control" name="priority"><option value="1">1 · Mais alta</option><option value="2">2</option><option value="3" selected>3 · Normal</option><option value="4">4</option><option value="5">5 · Baixa</option></select></div><div><label class="form-label">Tempo estimado · min</label><input class="form-control" name="estimatedMinutes" type="number" value="45" min="10" max="240"></div></div><label class="form-label">Caderno</label><select class="form-control" name="notebookId">${notebookOptions()}</select><label class="form-label">Data da avaliação (opcional)</label><input class="form-control" name="examDate" type="date"><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button">Criar assunto</button></div></form>`)}
function addNotebookModal(){openModal(`<h2>Novo caderno</h2><p class="modal-intro">Agrupe disciplinas e assuntos em cadernos independentes.</p><form id="notebook-form"><label class="form-label">Nome do caderno</label><input class="form-control" name="name" placeholder="Ex.: Medicina interna" required><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button">Criar caderno</button></div></form>`)}
function addReferenceModal(){openModal(`<h2>Adicionar fonte externa</h2><p class="modal-intro">Importe uma página HTTPS, PDF ou arquivo de texto; o conteúdo será extraído e poderá ser citado nas gerações por IA.</p><form id="reference-form"><label class="form-label">Título da fonte</label><input class="form-control" name="name" required placeholder="Ex.: Diretriz Brasileira de Hipertensão"><label class="form-label">URL</label><input class="form-control" name="url" type="url" required placeholder="https://..."><label class="form-label">Assunto</label><select class="form-control" name="subjectId"><option value="">Sem assunto</option>${subjectOptions()}</select><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button">Salvar referência</button></div></form>`)}
function addFlashcardModal(){openModal(`<h2>Criar flashcard</h2><p class="modal-intro">Escreva uma pergunta que ajude a recuperar o conceito.</p><form id="flashcard-form"><label class="form-label">Assunto</label><select class="form-control" name="subjectId"><option value="">Sem assunto</option>${subjectOptions()}</select><label class="form-label">Frente · pergunta</label><textarea class="form-control textarea" name="front" required></textarea><label class="form-label">Verso · resposta</label><textarea class="form-control textarea" name="back" required></textarea><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button">Salvar flashcard</button></div></form>`)}
function addSpaceModal(){openModal(`<h2>Criar espaço de estudo</h2><p class="modal-intro">Mantenha disciplinas e materiais em um ambiente separado.</p><form id="space-form"><label class="form-label">Nome do espaço</label><input class="form-control" name="name" required placeholder="Ex.: Preparação para residência"><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button">Criar espaço</button></div></form>`)}

document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
document.querySelector('.profile-button')?.addEventListener('click',()=>setView('settings'));
document.querySelector('#menu-toggle').addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open'));
document.querySelector('#space-select').addEventListener('change',async e=>{state.space=state.spaces.find(s=>s.id===Number(e.target.value));localStorage.setItem('study-space-id',String(state.space.id));await loadSpace();setView('dashboard')});
document.querySelector('#notifications').addEventListener('click',()=>setView('reviews'));
document.addEventListener('click',async e=>{
 const auth=e.target.closest('[data-auth]');if(auth){renderAuth(auth.dataset.auth);return}
 const nav=e.target.closest('[data-view-link]');if(nav){setView(nav.dataset.viewLink);return}
 const filter=e.target.closest('[data-review-filter]');if(filter){loadReviews(filter.dataset.reviewFilter);return}
 const btn=e.target.closest('[data-action]');if(!btn)return;const a=btn.dataset.action;
 try{
  if(a==='close-modal'){closeModal();return}if(a==='add-material'){addMaterialModal();return}if(a==='add-subject'){addSubjectModal();return}if(a==='add-notebook'){addNotebookModal();return}if(a==='add-reference'){addReferenceModal();return}if(a==='add-flashcard'){addFlashcardModal();return}if(a==='add-space'){addSpaceModal();return}
  if(a==='new-studio'){setView('studio');return}
  if(a==='material-detail'){const m=state.materials.find(x=>x.id===Number(btn.dataset.id));if(m)await materialDetailModal(m);return}
  if(a==='open-generated'){await openGenerated(Number(btn.dataset.id));return}
  if(a==='refresh-questions'){loadQuestions();return}
  if(a==='generate-plan'){const body=await api('/api/plans/generate',{method:'POST',body:JSON.stringify({})});toast('Plano atualizado.');if(state.view==='planning')loadPlan(body.week_start);else{state.dashboard=await api('/api/dashboard');render()}return}
  if(a==='planning-settings'){setView('settings');return}
  if(a==='toggle-plan-item'){const status=btn.dataset.status==='done'?'planned':'done';await api(`/api/plan-items/${btn.dataset.id}`,{method:'PATCH',body:JSON.stringify({status})});await loadPlan(document.querySelector('#week-start')?.value||mondayOf(currentDate()));return}
  if(a==='start-review'){await beginReview(Number(btn.dataset.id));return}
  if(a==='reschedule-review'){rescheduleModal(Number(btn.dataset.id));return}
  if(a==='load-cards'){await loadCards();return}
  if(a==='generate-cards'){generateCardsModal();return}
  if(a==='flip-card'){state.cardRevealed=true;renderFlashcardStage();return}
  if(a==='rate-card'){await rateCard(Number(btn.dataset.id),Number(btn.dataset.quality));return}
  if(a==='show-attempts'){await attemptsModal();return}
  if(a==='export-data'){const response=await fetch('/api/account/export',{credentials:'same-origin',headers:{'X-Space-Id':String(state.space.id)}});if(!response.ok)throw new Error('Não foi possível exportar seus dados.');downloadBlob(await response.blob(),'study-space-export.json');return}
  if(a==='logout'){await api('/api/auth/logout',{method:'POST'});state.user=null;renderAuth('login');return}
  if(a==='delete-account'){deleteAccountModal();return}
  if(a==='switch-space'){state.space=state.spaces.find(s=>s.id===Number(btn.dataset.id));await loadSpace();closeModal();setView('dashboard');return}
  if(a==='delete-material'){if(!confirm('Excluir este material, seu arquivo e o texto extraído?'))return;await api(`/api/materials/${btn.dataset.id}`,{method:'DELETE'});await refreshData();closeModal();render();toast('Material excluído.');return}
  if(a==='add-version'){versionModal(Number(btn.dataset.id));return}
  if(a==='edit-card'){const card=state.cards.find(c=>c.id===Number(btn.dataset.id));if(card)editFlashcardModal(card);return}
  if(a==='change-generated'){const id=Number(btn.dataset.id);await saveGenerated(id);return}
  if(a==='print-generated'){window.print();return}
  if(a==='start-session'){await startSessionFromForm();return}
  if(a==='submit-answer'){await submitAnswer(Number(btn.dataset.index));return}
  if(a==='next-question'){if(state.sessionIndex===state.session.questions.length-1){await finishSession()}else{state.sessionIndex++;renderActiveSession()}return}
  if(a==='leave-session'){if(confirm('Encerrar a sessão agora? As respostas já registradas permanecem no histórico.')){state.session=null;renderStudy()}return}
  if(a==='show-generated-sources'){toast('Fontes exibidas no painel do material.');return}
 }catch(error){showError(error)}
});

document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;const id=form.id;if(!id)return;e.preventDefault();const fd=new FormData(form);const values=Object.fromEntries(fd.entries());try{
 if(id==='login-form'||id==='signup-form'){const path=id==='login-form'?'/api/auth/login':'/api/auth/signup';await api(path,{method:'POST',body:JSON.stringify(values)});const me=await api('/api/auth/me');state.user=me.user;state.spaces=me.spaces||[];state.space=state.spaces[0]||null;await loadSpace();AUTH.hidden=true;document.querySelector('.app-shell').classList.remove('auth-hidden');setView('dashboard');return}
 if(id==='recovery-form'){const result=await api('/api/auth/recovery',{method:'POST',body:JSON.stringify(values)});renderAuth('login',result.message);return}
 if(id==='reset-form'){await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify(values)});history.replaceState(null,'','/');renderAuth('login','Sua senha foi atualizada. Entre com a nova senha.');return}
 if(id==='material-form'){const data=new FormData(form);await api('/api/materials',{method:'POST',body:data});closeModal();await refreshData();setView('library');toast('Arquivo enviado. O processamento está em andamento.');return}
 if(id==='material-edit-form'){await api(`/api/materials/${values.id}`,{method:'PATCH',body:JSON.stringify({name:values.name,subjectId:Number(values.subjectId)||null,notebookId:Number(values.notebookId)||null})});await refreshData();closeModal();render();toast('Detalhes atualizados.');return}
 if(id==='flashcard-edit-form'){await api(`/api/flashcards/${values.id}`,{method:'PATCH',body:JSON.stringify({front:values.front,back:values.back,subjectId:Number(values.subjectId)||null})});closeModal();await loadCards();toast('Flashcard atualizado.');return}
 if(id==='subject-form'){await api('/api/subjects',{method:'POST',body:JSON.stringify({...values,priority:Number(values.priority),estimatedMinutes:Number(values.estimatedMinutes),notebookId:Number(values.notebookId)||null,examDate:values.examDate||null})});await refreshData();closeModal();render();toast('Assunto criado.');return}
 if(id==='notebook-form'){await api('/api/notebooks',{method:'POST',body:JSON.stringify(values)});await refreshData();closeModal();render();toast('Caderno criado.');return}
 if(id==='reference-form'){await api('/api/materials/import-url',{method:'POST',body:JSON.stringify({...values,subjectId:Number(values.subjectId)||null})});await refreshData();closeModal();render();toast('Fonte importada; o processamento começou.');return}
 if(id==='flashcard-form'){await api('/api/flashcards',{method:'POST',body:JSON.stringify({...values,subjectId:Number(values.subjectId)||null})});closeModal();await loadCards();toast('Flashcard criado.');return}
 if(id==='space-form'){const space=await api('/api/spaces',{method:'POST',body:JSON.stringify(values)});state.spaces.push(space);state.space=space;await loadSpace();closeModal();setView('dashboard');return}
 if(id==='studio-form'){await submitStudio(form);return}
 if(id==='session-form'){await submitSessionConfig(form);return}
 if(id==='answer-form'){const answer=values.answer;await postAnswer(answer);return}
 if(id==='profile-form'){state.user=await api('/api/profile',{method:'PATCH',body:JSON.stringify(values)});syncShell();toast('Perfil atualizado.');return}
 if(id==='preferences-form'){const days=[...form.querySelectorAll('[name="availableDays"]:checked')].map(x=>Number(x.value));state.prefs=await api('/api/preferences',{method:'PATCH',body:JSON.stringify({...values,dailyMinutes:Number(values.dailyMinutes),weeklyMinutes:Number(values.weeklyMinutes),availableDays:days})});toast('Disponibilidade atualizada.');return}
 if(id==='password-form'){await api('/api/profile/password',{method:'POST',body:JSON.stringify(values)});form.reset();toast('Senha atualizada.');return}
 if(id==='reschedule-form'){await api(`/api/reviews/${values.id}/skip`,{method:'POST',body:JSON.stringify({dueAt:values.dueAt})});closeModal();await refreshData();renderReviews();toast('Revisão reprogramada.');return}
 if(id==='delete-account-form'){await api('/api/account',{method:'DELETE',body:JSON.stringify(values)});state.user=null;renderAuth('signup','A conta e os dados associados foram excluídos.');return}
 if(id==='version-form'){const data=new FormData(form);await api(`/api/materials/${values.materialId}/versions`,{method:'POST',body:data});closeModal();await refreshData();renderLibrary();toast('Nova versão enviada para processamento.');return}
 if(id==='generated-edit-form'){const idValue=Number(values.id);const row=await api(`/api/studio/materials/${idValue}`,{method:'PATCH',body:JSON.stringify({title:values.title,body:values.body})});toast(`Versão ${row.version} salva.`);await loadGenerated();await openGenerated(idValue);return}
 if(id==='flashcard-generate-form'){const res=await api('/api/flashcards/generate',{method:'POST',body:JSON.stringify({...values,subjectId:Number(values.subjectId),quantity:Number(values.quantity),materialIds:selectedFrom(form)})});closeModal();await loadCards();toast(`${res.cards.length} flashcards criados.`);return}
 }catch(error){showError(error)}});

document.addEventListener('change',async e=>{if(e.target.id==='flash-subject'){await loadCards();return}if(e.target.matches('[data-plan-date]')){try{await api(`/api/plan-items/${e.target.dataset.planDate}`,{method:'PATCH',body:JSON.stringify({scheduledFor:e.target.value})});toast('Atividade reprogramada.')}catch(err){showError(err)}}});

async function refreshData(){const data=await api('/api/bootstrap');Object.assign(state,{space:data.space,spaces:data.spaces||state.spaces,prefs:data.prefs,notebooks:data.notebooks||[],subjects:data.subjects||[],materials:data.materials||[],dashboard:data.dashboard,aiAvailable:data.aiAvailable})}
function addQuery(q){const param=new URLSearchParams(q);return param.toString()}
function requireAi(){if(!state.aiAvailable)throw new Error('A IA ainda não está configurada. Adicione OPENAI_API_KEY ao .env do servidor.');}

async function materialDetailModal(m){let versions=[];try{versions=await api(`/api/materials/${m.id}/versions`)}catch{}openModal(`<h2>${esc(m.name)}</h2><p class="modal-intro">${esc(m.original_name)} · ${esc(m.subject_name||'Sem assunto')} · ${formatBytes(m.file_size)} · status ${statusText(m.process_status)}</p>${m.process_error?`<div class="form-alert">${esc(m.process_error)}</div>`:''}<form id="material-edit-form"><input type="hidden" name="id" value="${m.id}"><label class="form-label">Nome</label><input class="form-control" name="name" value="${esc(m.name)}"><label class="form-label">Assunto</label><select class="form-control" name="subjectId"><option value="">Sem assunto</option>${subjectOptions(m.subject_id)}</select><label class="form-label">Caderno</label><select class="form-control" name="notebookId">${notebookOptions(m.notebook_id)}</select><div class="form-actions"><button type="button" class="button danger" data-action="delete-material" data-id="${m.id}">Excluir</button><button type="button" class="button secondary" data-action="add-version" data-id="${m.id}">Enviar nova versão</button><button class="button">Salvar detalhes</button></div></form><div class="version-list"><strong>Histórico de versões</strong>${versions.map(v=>`<div><span>v${v.version} · ${esc(v.original_name)} · ${statusText(v.process_status)}</span><a href="/api/materials/${m.id}/versions/${v.version}/file">Baixar ↗</a></div>`).join('')}</div>`)}
function versionModal(id){openModal(`<h2>Enviar uma nova versão</h2><p class="modal-intro">A versão anterior será preservada no histórico.</p><form id="version-form"><input type="hidden" name="materialId" value="${id}"><label class="form-label">Novo arquivo</label><input type="file" name="file" class="form-control file-input" required accept=".pdf,.ppt,.pptx,.doc,.docx,.txt,.md,.csv"><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button">Enviar nova versão</button></div></form>`)}

async function loadGenerated(){state.generated=await api('/api/studio/materials')}
async function submitStudio(form){requireAi();const materialIds=selectedFrom(form);if(!materialIds.length)throw new Error('Selecione ao menos uma fonte processada.');const vals=Object.fromEntries(new FormData(form).entries());const row=await api('/api/studio/generate',{method:'POST',body:JSON.stringify({...vals,subjectId:Number(vals.subjectId)||null,materialIds})});await loadGenerated();await refreshData();await openGenerated(row.material.id);toast('Material gerado com referências.');}
async function openGenerated(id){const data=await api(`/api/studio/materials/${id}`);openModal(`<div class="generated-editor"><div class="generated-editor-head"><div><span class="eyebrow">${esc(data.material.kind)} · VERSÃO ${data.material.version}</span><h2>Revise seu material</h2></div><button class="button secondary" data-action="print-generated">Exportar / imprimir PDF</button></div><form id="generated-edit-form"><input type="hidden" name="id" value="${id}"><label class="form-label">Título</label><input class="form-control" name="title" value="${esc(data.material.title)}"><label class="form-label">Conteúdo editável</label><textarea class="form-control generated-textarea" name="body">${esc(data.material.body)}</textarea><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Fechar</button><button class="button">Salvar versão ${data.material.version+1}</button></div></form><section class="citation-panel"><strong>Fontes utilizadas</strong>${data.sources.map(s=>`<div class="citation-source"><span class="citation">${esc(s.citation)}</span><span><b>${esc(s.materialName)}</b><small>${s.page?`Página ${s.page}`:'Página não disponível'} · ${esc(s.excerpt).slice(0,210)}…</small></span></div>`).join('')||'<p class="helper">Nenhuma citação anexada.</p>'}</section><section class="versions-inline"><strong>Histórico</strong>${data.versions.map(v=>`<span>v${v.version} · ${dateFmt(v.created_at,{day:'numeric',month:'short',year:'numeric'})}</span>`).join(' · ')}</section></div>`)}

async function submitSessionConfig(form){requireAi();const values=Object.fromEntries(new FormData(form).entries());const materialIds=selectedFrom(form);if(!materialIds.length)throw new Error('Selecione ao menos um material processado.');const started=await api('/api/study/sessions',{method:'POST',body:JSON.stringify({...values,subjectId:Number(values.subjectId),quantity:Number(values.quantity),materialIds})});state.session={...started,correct:0};state.sessionIndex=0;state.sessionResults=[];state.timerStarted=Date.now();renderActiveSession()}
async function startSessionFromForm(){const form=document.querySelector('#session-form');if(form)await submitSessionConfig(form)}
async function beginReview(id){requireAi();const review=await api(`/api/reviews`);const found=review.find(r=>r.id===id);if(!found)throw new Error('Revisão não encontrada.');const materialIds=state.materials.filter(m=>m.subject_id===found.subject_id&&m.process_status==='ready').map(m=>m.id);if(!materialIds.length)throw new Error('Adicione e processe um material para este assunto antes de iniciar a revisão.');const started=await api(`/api/reviews/${id}/session`,{method:'POST',body:JSON.stringify({materialIds,quantity:5,type:'multiple_choice',difficulty:'mixed'})});state.session={...started,correct:0};state.sessionIndex=0;state.sessionResults=[];state.timerStarted=Date.now();setView('study');state.session={...started,correct:0};renderActiveSession()}
async function submitAnswer(index){const q=state.session.questions[state.sessionIndex];await postAnswer(index);}
async function postAnswer(answer){const q=state.session.questions[state.sessionIndex],seconds=Math.max(0,Math.round((Date.now()-state.timerStarted)/1000));const result=await api('/api/study/attempts',{method:'POST',body:JSON.stringify({sessionId:state.session.sessionId,questionId:q.id,answer,durationSeconds:seconds})});result.submittedAnswer=answer;state.sessionResults[state.sessionIndex]=result;if(result.correct)state.session.correct=(state.session.correct||0)+1;renderActiveSession()}
async function finishSession(){const completed=await api(`/api/study/sessions/${state.session.sessionId}/complete`,{method:'POST',body:JSON.stringify({})});const finished=state.session;const results=state.sessionResults;const right=results.filter(r=>r?.correct).length;state.session=null;state.sessionIndex=0;state.sessionResults=[];await refreshData();content.innerHTML=`${heading('SESSÃO CONCLUÍDA','Você praticou ${esc(finished.subject.name)}.','Cada tentativa fica registrada no histórico do seu espaço.') }<section class="panel completion-panel"><span class="eyebrow">SEU RESULTADO</span><h2>${right} de ${finished.questions.length} acertos</h2><p>Desempenho médio: ${Math.round(results.reduce((n,r)=>n+(r?.score||0),0)/Math.max(1,results.length)*100)}%</p>${completed.reviews?.length?`<div class="completion-cycle"><strong>Próximas revisões</strong><span>${completed.reviews.map(r=>`${dateFmt(r.due_at,{day:'numeric',month:'short'})} · ${[7,14,21,30][r.stage-1]} dias`).join(' &nbsp; · &nbsp; ')}</span></div>`:''}<div class="form-actions"><button class="button" data-view-link="reviews">Ver ciclos de revisão →</button><button class="button secondary" data-view-link="performance">Analisar desempenho</button></div></section>`;if(finished.reviewId)setView('reviews');else{state.view='study';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view==='study'))}}

function editFlashcardModal(card){openModal(`<h2>Editar flashcard</h2><form id="flashcard-edit-form"><input type="hidden" name="id" value="${card.id}"><label class="form-label">Assunto</label><select class="form-control" name="subjectId"><option value="">Sem assunto</option>${subjectOptions(card.subject_id)}</select><label class="form-label">Frente</label><textarea class="form-control textarea" name="front" required>${esc(card.front)}</textarea><label class="form-label">Verso</label><textarea class="form-control textarea" name="back" required>${esc(card.back)}</textarea><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button">Salvar</button></div></form>`)}
async function loadCards(){try{const subjectId=document.querySelector('#flash-subject')?.value;const query=subjectId?`?subjectId=${subjectId}`:'';state.cards=await api(`/api/flashcards${query}`);state.activeCard=0;state.cardRevealed=false;renderFlashcardStage()}catch(e){showError(e)}}
function renderFlashcardStage(){const stage=document.querySelector('#flashcard-stage'),list=document.querySelector('#flashcard-list');if(!stage)return;const due=state.cards.filter(c=>!c.due_at||c.due_at.slice(0,10)<=currentDate());if(!state.cards.length){stage.innerHTML=`<div class="flashcard-empty"><div class="flashcard-empty-icon">▣</div><h2>Crie seu primeiro cartão.</h2><p>Escreva cartões manualmente ou gere um conjunto a partir de materiais processados.</p><button class="button" data-action="add-flashcard">Criar flashcard</button> ${state.aiAvailable?'<button class="button secondary" data-action="generate-cards">Gerar com IA</button>':''}</div>`}else if(!due.length){stage.innerHTML=`<div class="flashcard-empty"><div class="flashcard-empty-icon">✓</div><h2>Cartões em dia.</h2><p>Não há cartões vencidos neste filtro. Você tem ${state.cards.length} cartões cadastrados.</p></div>`}else{const card=due[Math.min(state.activeCard,due.length-1)];stage.innerHTML=`<article class="flashcard"><div class="flashcard-top"><span>${esc(card.subject_name||'Sem assunto')}</span><span>${Math.min(state.activeCard+1,due.length)} / ${due.length} para revisar</span></div><div class="flashcard-content"><span class="eyebrow">${state.cardRevealed?'RESPOSTA':'LEMBRE-SE'}</span><p>${esc(state.cardRevealed?card.back:card.front)}</p></div><div class="flashcard-bottom">${state.cardRevealed?`<span>Como foi lembrar?</span><div class="rating-buttons"><button data-action="rate-card" data-id="${card.id}" data-quality="1">Esqueci</button><button data-action="rate-card" data-id="${card.id}" data-quality="3">Difícil</button><button data-action="rate-card" data-id="${card.id}" data-quality="4">Lembrei</button><button data-action="rate-card" data-id="${card.id}" data-quality="5">Fácil</button></div>`:`<button class="button" data-action="flip-card">Mostrar resposta</button>`}</div></article>`}if(list)list.innerHTML=state.cards.length?state.cards.map(c=>`<div class="flash-list-row"><div><strong>${esc(c.front)}</strong><small>${esc(c.subject_name||'Sem assunto')} · próxima: ${dateFmt(c.due_at)}</small></div><button class="text-link" data-action="edit-card" data-id="${c.id}">Editar</button></div>`).join(''):'<p class="study-note">Seus flashcards aparecerão aqui.</p>'}
async function rateCard(id,quality){const data=await api(`/api/flashcards/${id}/review`,{method:'POST',body:JSON.stringify({quality})});state.cards=state.cards.map(c=>c.id===id?data.card:c);state.activeCard=0;state.cardRevealed=false;renderFlashcardStage();await refreshData();toast(`Próxima revisão em ${data.intervalDays} dia${data.intervalDays===1?'':'s'}.`)}
function generateCardsModal(){if(!state.subjects.length)throw new Error('Crie um assunto antes de gerar flashcards.');openModal(`<h2>Gerar flashcards</h2><p class="modal-intro">Os cartões serão salvos e vinculados às fontes selecionadas.</p><form id="flashcard-generate-form"><label class="form-label">Assunto</label><select class="form-control" name="subjectId" required>${subjectOptions()}</select><label class="form-label">Fontes processadas</label>${sourceChoices()}<label class="form-label">Quantidade</label><input class="form-control" type="number" name="quantity" min="2" max="40" value="12"><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button" ${state.aiAvailable?'':'disabled'}>Gerar flashcards →</button></div></form>`)}

function rescheduleModal(id){openModal(`<h2>Reprogramar revisão</h2><p class="modal-intro">Escolha uma nova data para esta etapa do ciclo.</p><form id="reschedule-form"><input type="hidden" name="id" value="${id}"><label class="form-label">Nova data</label><input class="form-control" name="dueAt" type="date" min="${currentDate()}" value="${datePlus(1)}" required><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button">Salvar data</button></div></form>`)}
function datePlus(days){const d=new Date();d.setDate(d.getDate()+days);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function deleteAccountModal(){openModal(`<h2>Excluir permanentemente?</h2><p class="modal-intro">Esta ação remove a conta, todos os espaços, documentos enviados e registros de aprendizagem. Digite sua senha para confirmar.</p><form id="delete-account-form"><label class="form-label">Senha</label><input class="form-control" type="password" name="password" required><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button class="button danger">Excluir tudo</button></div></form>`)}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function attemptsModal(){const rows=await api('/api/attempts');openModal(`<h2>Histórico de respostas</h2><p class="modal-intro">${rows.length} tentativas registradas no espaço.</p><div class="attempt-modal-list">${rows.length?rows.map(a=>`<div class="history-row"><span class="history-result ${a.is_correct?'correct':'incorrect'}">${a.is_correct?'✓':'×'}</span><span><strong>${esc(a.subject_name||'Assunto')}</strong><small>${esc(a.prompt||'Questão removida')}</small><small>Sua resposta: ${esc(typeof a.answer==='string'?a.answer:JSON.stringify(a.answer))}</small><small>${esc(a.feedback)}</small></span><small>${dateFmt(a.attempted_at)}</small></div>`).join(''):'<p class="study-note">Sem tentativas.</p>'}</div>`)}

async function saveGenerated(id){const form=document.querySelector('#generated-edit-form');const values=Object.fromEntries(new FormData(form).entries());const result=await api(`/api/studio/materials/${id}`,{method:'PATCH',body:JSON.stringify(values)});await loadGenerated();await openGenerated(id);toast(`Versão ${result.version} salva.`)}

function renderFormLoading(form){const submit=form.querySelector('button[type="submit"],button:not([type])');if(submit){submit.disabled=true;submit.dataset.original=submit.textContent;submit.textContent='Processando…'}}
function handleAsyncError(form,error){const old=form.querySelector('.form-alert');if(old)old.remove();const el=document.createElement('div');el.className='form-alert';el.textContent=error.message||'Não foi possível concluir.';form.prepend(el);const submit=form.querySelector('button[disabled]');if(submit){submit.disabled=false;submit.textContent=submit.dataset.original||'Tentar novamente'}}

async function initialRender(){if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('/sw.js').catch(()=>{});await boot();document.querySelector('#space-select').addEventListener('change',async e=>{try{state.space=state.spaces.find(s=>s.id===Number(e.target.value));await loadSpace();setView('dashboard')}catch(error){showError(error)}})}
initialRender();
setInterval(async()=>{if(!state.user)return;try{const rows=await api('/api/materials');const changed=JSON.stringify(rows.map(m=>[m.id,m.process_status,m.process_error]))!==JSON.stringify(state.materials.map(m=>[m.id,m.process_status,m.process_error]));if(changed){state.materials=rows;if(state.view==='library')renderLibrary()}}catch{}},3500);
